import { test, expect, Page, BrowserContext } from '@playwright/test';
import { createDemoProject, createProject, drawWall, createFurniture, uid, validateProject } from '@sh3d/home-model';
async function startDemo(page:Page):Promise<void>{await page.goto('/');await page.getByRole('button',{name:/Esplora la demo/}).click();await expect(page.locator('sh3d-scene canvas')).toBeVisible();}
async function clickWorld(page:Page,x:number,y:number):Promise<void>{const point=await page.locator('svg.editor-svg').evaluate((svg,p)=>{const m=(svg as SVGSVGElement).getScreenCTM()!;const q=new DOMPoint(p.x,p.y).matrixTransform(m);return {x:q.x,y:q.y};},{x,y});await page.mouse.click(point.x,point.y);}

test('scopes consumption devices to the current house and their own HA measurements',async({page,context})=>{
  const errors:string[]=[];page.on('pageerror',error=>errors.push(error.message));
  const house=createDemoProject(),binding=house.bindings.find(b=>b.entityId.startsWith('light.'))!;
  house.bindings=[{...binding,provider:'home-assistant',entityId:'light.personal',relatedEntityIds:[]}];
  const states=[
    {entity_id:'light.personal',state:'on',attributes:{friendly_name:'Lampada personale'}},
    {entity_id:'sensor.personal_power',state:'12',attributes:{friendly_name:'Potenza personale',unit_of_measurement:'W'}},
    {entity_id:'sensor.personal_energy',state:'2',attributes:{friendly_name:'Energia personale',unit_of_measurement:'kWh'}},
    {entity_id:'light.unrelated',state:'on',attributes:{friendly_name:'Lampada altra casa'}},
    {entity_id:'sensor.unrelated_power',state:'50',attributes:{friendly_name:'Potenza altra casa',unit_of_measurement:'W'}}
  ];
  await fakeHouseServer(page,context,house,states,[{entity_id:'light.personal',device_id:'personal'},{entity_id:'sensor.personal_power',device_id:'personal'},{entity_id:'sensor.personal_energy',device_id:'personal'},{entity_id:'sensor.unrelated_power',device_id:'other'}]);
  await page.getByRole('link',{name:/Consumi/}).click();await page.locator('.energy-tabs').getByRole('button',{name:'Dispositivi',exact:true}).click();
  const choices=page.getByRole('combobox',{name:'Entità dispositivo',exact:true});await expect(choices.locator('option')).toHaveCount(2);await expect(choices).not.toContainText('altra casa');
  await choices.selectOption('light.personal');await page.getByRole('combobox',{name:'Metodo di consumo',exact:true}).selectOption('power');const sensors=page.getByRole('combobox',{name:'Entità sensore di consumo',exact:true});
  await expect(sensors.locator('option')).toHaveCount(2);await expect(sensors).toContainText('Potenza personale');await expect(sensors).not.toContainText('Energia personale');await expect(sensors).not.toContainText('altra casa');
  await sensors.selectOption('sensor.personal_power');await page.getByRole('button',{name:'Aggiungi dispositivo',exact:true}).click();await page.getByRole('button',{name:'Salva configurazione',exact:true}).click();
  await expect(page.locator('.profile-detail')).toHaveCount(1);await page.reload();await page.locator('.energy-tabs').getByRole('button',{name:'Dispositivi',exact:true}).click();await expect(page.locator('.profile-detail')).toContainText('Lampada personale');
  await page.getByRole('link',{name:/Impostazioni/}).click();await page.getByRole('textbox',{name:'Nome nuovo progetto',exact:true}).fill('Casa senza associazioni');await page.getByRole('button',{name:'＋ Crea progetto',exact:true}).click();await page.getByRole('link',{name:/Consumi/}).click();await page.locator('.energy-tabs').getByRole('button',{name:'Dispositivi',exact:true}).click();await expect(choices.locator('option')).toHaveCount(1);expect(errors).toEqual([]);
});

test('saves dashboard temperatures per house, prefers its thermometer and falls back to HA weather',async({page,context})=>{
  const errors:string[]=[];page.on('pageerror',error=>errors.push(error.message));
  const house=createDemoProject();house.name='Casa temperature';
  const states=[
    {entity_id:'sensor.indoor',state:'21.4',attributes:{friendly_name:'Termometro soggiorno',unit_of_measurement:'°C',device_class:'temperature'}},
    {entity_id:'sensor.outdoor',state:'0',attributes:{friendly_name:'Termometro balcone',unit_of_measurement:'°C',device_class:'temperature'}},
    {entity_id:'weather.local',state:'sunny',attributes:{friendly_name:'Meteo della mia località',temperature:12.5,temperature_unit:'°C'}}
  ];
  const push=await fakeHouseServer(page,context,house,states);
  await page.getByRole('button',{name:'Configura temperatura esterna',exact:true}).click();
  await page.getByRole('combobox',{name:'Sensore temperatura interna',exact:true}).selectOption('sensor.indoor');await page.getByRole('combobox',{name:'Sensore temperatura esterna',exact:true}).selectOption('sensor.outdoor');await page.getByRole('combobox',{name:'Meteo localizzato di Home Assistant',exact:true}).selectOption('weather.local');
  await expect(page.locator('.indoor-temperature strong')).toHaveText('21,4 °C');await expect(page.locator('.outdoor-temperature strong')).toHaveText('0 °C');await expect(page.locator('.outdoor-temperature .weather-source')).toHaveCount(0);
  states[1].state='unavailable';push(states[1]);await expect(page.locator('.outdoor-temperature strong')).toHaveText('12,5 °C');await expect(page.locator('.outdoor-temperature .weather-source')).toHaveText('Meteo HA');
  const fallback=page.getByRole('checkbox',{name:'Usa il meteo HA quando il termometro esterno manca o non è disponibile',exact:true});await fallback.uncheck();await expect(page.locator('.outdoor-temperature strong')).toHaveText('— °C');await fallback.check();
  await page.getByRole('combobox',{name:'Sensore temperatura esterna',exact:true}).selectOption('');await page.getByRole('button',{name:/Salva progetto|Salvato/}).click();await page.reload();
  await expect(page.locator('.indoor-temperature strong')).toHaveText('21,4 °C');await expect(page.locator('.outdoor-temperature strong')).toHaveText('12,5 °C');
  await page.getByRole('button',{name:'Configura temperatura esterna',exact:true}).click();await expect(page.getByRole('combobox',{name:'Sensore temperatura esterna',exact:true})).toHaveValue('');await expect(page.getByRole('combobox',{name:'Meteo localizzato di Home Assistant',exact:true})).toHaveValue('weather.local');
  await page.setViewportSize({width:390,height:844});expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);await page.screenshot({path:'test-results/temperatures-mobile.png',fullPage:true});
  await page.getByRole('link',{name:/Impostazioni/}).click();const download=page.waitForEvent('download');await page.getByRole('button',{name:'↓ Esporta JSON',exact:true}).click();const file=await download;const stream=await file.createReadStream();const chunks:Buffer[]=[];for await(const chunk of stream!)chunks.push(chunk);expect(JSON.parse(Buffer.concat(chunks).toString()).dashboard).toEqual({indoorTemperatureEntityId:'sensor.indoor',outdoorTemperatureEntityId:'',outdoorWeatherEntityId:'weather.local',useWeatherFallback:true});expect(errors).toEqual([]);
});

