async function fakeHouseServer(page:Page,context:BrowserContext,house:ReturnType<typeof createDemoProject>,states:{entity_id:string;state:string;attributes:Record<string,unknown>}[],registry:Record<string,string>[]=[]):Promise<(state:typeof states[number])=>void>{
  const backend='http://127.0.0.1:8098',projects=new Map([[house.id,house]]);let push=(_state:typeof states[number])=>{};
  await context.route(backend+'/api/v1/**',async route=>{
    const request=route.request(),path=new URL(request.url()).pathname.replace('/api/v1',''),method=request.method();const headers={'Access-Control-Allow-Origin':'http://127.0.0.1:4307','Access-Control-Allow-Credentials':'true','Access-Control-Allow-Headers':'Content-Type,X-SH3D-CSRF,If-Match,If-None-Match','Access-Control-Allow-Methods':'GET,POST,PUT,DELETE,OPTIONS','Access-Control-Expose-Headers':'ETag',ETag:'"1"'};let body:unknown={},status=200;
    if(method==='OPTIONS'){await route.fulfill({status:204,headers});return;}
    if(path==='/session')body={authenticated:true,setupRequired:false,username:'test-owner',csrfToken:'test-csrf',homeAssistant:{configured:true,url:'http://ha.test',connected:true}};
    else if(path==='/projects')body=[...projects.values()].map(project=>({project,revision:1}));
    else if(path==='/profile')body={activeProject:house.id};
    else if(path.startsWith('/projects/')){const id=path.split('/')[2];if(method==='PUT')projects.set(id,request.postDataJSON());else if(path.includes('/energy/'))body={year:2026,months:Array.from({length:12},(_,i)=>({month:'2026-'+String(i+1).padStart(2,'0'),electricity:null,gas:null,devices:[]})),monthly:[]};else{body=projects.get(id);if(!body)status=404;}}
    await route.fulfill({status,headers,contentType:'application/json',body:JSON.stringify(body)});
  });
  await context.routeWebSocket(backend.replace('http:','ws:')+'/api/v1/ha/ws',socket=>{
    push=state=>socket.send(JSON.stringify({type:'event',event:{event_type:'state_changed',data:{entity_id:state.entity_id,new_state:state}}}));
    socket.send(JSON.stringify({type:'auth_required'}));socket.onMessage(data=>{const message=JSON.parse(String(data));if(message.type==='auth'){socket.send(JSON.stringify({type:'auth_ok'}));return;}const result=message.type==='get_states'?states:message.type==='get_services'?{}:message.type==='config/entity_registry/list'?registry:[];socket.send(JSON.stringify({id:message.id,type:'result',success:true,result}));});
  });
  await startDemo(page);await page.getByRole('button',{name:/Salva progetto|Salvato/}).click();await page.evaluate(async backend=>{const db=await new Promise<IDBDatabase>(resolve=>{const request=indexedDB.open('smart-home-3d');request.onsuccess=()=>resolve(request.result);});await new Promise<void>((resolve,reject)=>{const tx=db.transaction('preferences','readwrite');tx.objectStore('preferences').put({id:'backend-url',value:backend});tx.objectStore('preferences').put({id:'storage-mode',value:'server'});tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);});db.close();},backend);await page.reload();await expect(page.locator('.connection-detail')).toContainText('connesso');await expect(page.locator('.project-heading')).toContainText(house.name);return state=>push(state);
}
test('restores the owner house and HA bindings after server login without another HA authorization',async({page,context})=>{
  const errors:string[]=[];page.on('pageerror',error=>errors.push(error.message));const backend='http://127.0.0.1:8098',house=createDemoProject();house.id='owner-selected-house';house.name='Casa del profilo';house.updatedAt='2026-11-01T12:00:00Z';const binding=house.bindings.find(b=>b.entityId.startsWith('light.'))!;binding.provider='home-assistant';binding.entityId='light.profile_lamp';
  const recent=createProject('Altra casa più recente'),projects=new Map([house,recent].map(p=>[p.id,p]));let authenticated=false,active=house.id,authorizations=0,state='off',commands=0;
  await context.route(backend+'/api/v1/**',async route=>{
    const request=route.request(),path=new URL(request.url()).pathname.replace('/api/v1',''),method=request.method(),headers={'Access-Control-Allow-Origin':'http://127.0.0.1:4307','Access-Control-Allow-Credentials':'true','Access-Control-Allow-Headers':'Content-Type,X-SH3D-CSRF,If-Match,If-None-Match','Access-Control-Allow-Methods':'GET,POST,PUT,DELETE,OPTIONS','Access-Control-Expose-Headers':'ETag',ETag:'"1"'};let body:unknown={};let status=200;
    if(method==='OPTIONS'){await route.fulfill({status:204,headers});return;}
    if(path==='/session')body={authenticated,setupRequired:false,username:authenticated?'test-profile-owner':'',csrfToken:'test-profile-csrf',homeAssistant:{configured:true,url:'http://ha.test:8123',connected:authenticated}};
    else if(path==='/auth/login'){expect(request.postDataJSON()).toEqual({username:'test-profile-owner',password:'test-profile-password-42!'});authenticated=true;}
    else if(!authenticated)status=401;
    else if(path==='/projects')body=[...projects.values()].map(project=>({project,revision:1}));
    else if(path==='/profile')body={activeProject:active};
    else if(path==='/profile/active-project')active=request.postDataJSON().projectId;
    else if(path.startsWith('/projects/')){const id=path.split('/')[2];if(method==='PUT')projects.set(id,request.postDataJSON());else body=projects.get(id);}
    else if(path==='/ha/authorize'){authorizations++;status=500;}
    await route.fulfill({status,headers,contentType:'application/json',body:JSON.stringify(body)});
  });
  await context.routeWebSocket(backend.replace('http:','ws:')+'/api/v1/ha/ws',socket=>{socket.send(JSON.stringify({type:'auth_required'}));socket.onMessage(data=>{const message=JSON.parse(String(data));if(message.type==='auth'){expect(message).toEqual({type:'auth'});socket.send(JSON.stringify({type:'auth_ok'}));return;}let result:unknown=[];if(message.type==='get_states')result=[{entity_id:'light.profile_lamp',state,attributes:{friendly_name:'Lampada del profilo',supported_features:0}}];if(message.type==='get_services')result={};if(message.type==='call_service'){expect(message.target.entity_id).toBe('light.profile_lamp');commands++;state='on';socket.send(JSON.stringify({type:'event',event:{event_type:'state_changed',data:{entity_id:'light.profile_lamp',new_state:{entity_id:'light.profile_lamp',state,attributes:{friendly_name:'Lampada del profilo'}}}}}));}socket.send(JSON.stringify({id:message.id,type:'result',success:true,result}));});});
  await startDemo(page);await page.getByRole('button',{name:/Salva progetto|Salvato/}).click();await page.evaluate(async backend=>{const db=await new Promise<IDBDatabase>(resolve=>{const request=indexedDB.open('smart-home-3d');request.onsuccess=()=>resolve(request.result);});await new Promise<void>((resolve,reject)=>{const tx=db.transaction('preferences','readwrite');for(const [id,value]of [['backend-url',backend],['storage-mode','server']])tx.objectStore('preferences').put({id,value});tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);});db.close();},backend);
  await page.reload();await expect(page.locator('.archive-pending')).toBeVisible();await page.locator('.archive-pending').getByRole('link',{name:'Accedi al server',exact:true}).click();const storage=page.locator('sh3d-storage-settings');await storage.getByRole('textbox',{name:'Utente server',exact:true}).fill('test-profile-owner');await storage.getByLabel('Password server',{exact:true}).fill('test-profile-password-42!');await storage.getByRole('button',{name:'Accedi al server',exact:true}).click();
  await expect(page.locator('.project-heading')).toContainText('Casa del profilo');await expect(page.locator('.storage-location')).toHaveText('Archivio server');await expect(page.locator('.archive-pending')).toHaveCount(0);await expect(page.locator('.connection-pill')).toContainText('Home Assistant');await expect(page.locator('.connection-detail')).toContainText('connesso');
  await page.getByRole('link',{name:/Dashboard/}).click();await page.locator('.device-card').filter({hasText:'Luce soggiorno'}).click();await expect(page.getByRole('combobox',{name:'Associa entità',exact:true})).toHaveValue('light.profile_lamp');await page.getByRole('button',{name:'⏻ Accendi',exact:true}).click();await expect.poll(()=>commands).toBe(1);
  await page.reload();await expect(page.locator('.project-heading')).toContainText('Casa del profilo');await expect(page.locator('.connection-detail')).toContainText('connesso');expect(authorizations).toBe(0);expect(errors).toEqual([]);
});
