test('signs in through a PKCE popup without persisting credentials, rejects an invalid callback and revokes logout',async({page,context})=>{
  const errors:string[]=[];page.on('pageerror',error=>errors.push(error.message));let exchanges=0,revoked=false,challenge='',authorizations=0;
  await context.route('http://ha.test:8123/auth/authorize**',async route=>{const url=new URL(route.request().url());challenge=url.searchParams.get('code_challenge')!;expect(url.searchParams.get('code_challenge_method')).toBe('S256');const callback=new URL(url.searchParams.get('redirect_uri')!);callback.search=new URLSearchParams({code:'e2e-code',state:++authorizations===1?url.searchParams.get('state')!:'mismatch'}).toString();await route.fulfill({contentType:'text/html',body:`<button onclick="location.href='${callback.toString()}'">Consenti</button>`});});
  await context.route('http://ha.test:8123/auth/token',async route=>{exchanges++;const form=new URLSearchParams(route.request().postData()!);expect(form.get('grant_type')).toBe('authorization_code');expect(form.get('code')).toBe('e2e-code');const crypto=await import('node:crypto');expect(crypto.createHash('sha256').update(form.get('code_verifier')!).digest('base64url')).toBe(challenge);await route.fulfill({contentType:'application/json',headers:{'Access-Control-Allow-Origin':'*'},body:JSON.stringify({access_token:'e2e-access-ephemeral',refresh_token:'e2e-refresh-ephemeral',token_type:'Bearer',expires_in:1800})});});
  await context.route('http://ha.test:8123/auth/revoke',async route=>{revoked=new URLSearchParams(route.request().postData()!).get('token')==='e2e-refresh-ephemeral';await route.fulfill({status:200,headers:{'Access-Control-Allow-Origin':'*'},body:''});});
  await context.routeWebSocket('ws://ha.test:8123/api/websocket',socket=>{socket.send(JSON.stringify({type:'auth_required'}));socket.onMessage(data=>{const message=JSON.parse(String(data));if(message.type==='auth'){expect(message.access_token).toBe('e2e-access-ephemeral');socket.send(JSON.stringify({type:'auth_ok'}));}else socket.send(JSON.stringify({id:message.id,type:'result',success:true,result:message.type==='get_services'?{}:[]}));});});
  await startDemo(page);await page.getByRole('link',{name:/Impostazioni/}).click();await page.getByRole('textbox',{name:'URL Home Assistant',exact:true}).fill('http://ha.test:8123');
  const firstPopup=page.waitForEvent('popup');await page.getByRole('button',{name:'Accedi con Home Assistant',exact:true}).click();const popup=await firstPopup;await expect(popup.getByRole('button',{name:'Consenti',exact:true})).toBeVisible();
  await page.evaluate(()=>window.postMessage({type:'sh3d-ha-auth',code:'forged',state:'forged'},location.origin));expect(exchanges).toBe(0);
  await popup.getByRole('button',{name:'Consenti',exact:true}).click();await expect(page.getByText(/Sessione attiva: rinnovo automatico/)).toBeVisible();await expect(page.locator('.connection-pill')).toContainText('connesso');expect(exchanges).toBe(1);
  expect(await page.evaluate(()=>JSON.stringify([Object.entries(localStorage),Object.entries(sessionStorage)]))).not.toMatch(/e2e-access|e2e-refresh|e2e-code/);
  const leak=await page.evaluate(async()=>{const names=await indexedDB.databases();for(const entry of names){const db=await new Promise<IDBDatabase>((resolve,reject)=>{const request=indexedDB.open(entry.name!);request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});for(const name of Array.from(db.objectStoreNames)){const values=await new Promise<unknown[]>((resolve,reject)=>{const request=db.transaction(name).objectStore(name).getAll();request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});if(/e2e-access|e2e-refresh|e2e-code/.test(JSON.stringify(values)))return true;}db.close();}return false;});expect(leak).toBe(false);
  await page.getByRole('button',{name:'Disconnetti',exact:true}).click();await expect.poll(()=>revoked).toBe(true);
  const secondPopup=page.waitForEvent('popup');await page.getByRole('button',{name:'Accedi con Home Assistant',exact:true}).click();const invalid=await secondPopup;await expect(invalid.getByRole('button',{name:'Consenti',exact:true})).toBeVisible();await invalid.getByRole('button',{name:'Consenti',exact:true}).click();await expect(page.getByRole('alert')).toContainText('Risposta di accesso non valida');expect(exchanges).toBe(1);await page.reload();await expect(page.locator('.connection-pill')).toContainText('Modalità demo');expect(errors).toEqual([]);
});

test('reviews an opening on an oblique floor and exports a valid editable window',async({page})=>{
  const errors:string[]=[];page.on('pageerror',error=>errors.push(error.message));await startDemo(page);await page.getByRole('link',{name:/Editor casa/}).click();
  const image=await page.evaluate(()=>{const canvas=document.createElement('canvas');canvas.width=400;canvas.height=300;const ctx=canvas.getContext('2d')!;ctx.fillStyle='white';ctx.fillRect(0,0,400,300);ctx.strokeStyle='black';ctx.lineWidth=8;ctx.beginPath();ctx.moveTo(70,35);ctx.lineTo(320,110);ctx.lineTo(320,260);ctx.lineTo(70,185);ctx.closePath();ctx.stroke();ctx.fillRect(314,177,12,18);return canvas.toDataURL().split(',')[1];});
  await page.getByLabel('Importa planimetria',{exact:true}).setInputFiles({name:'obliqua-apertura.png',mimeType:'image/png',buffer:Buffer.from(image,'base64')});await page.getByRole('button',{name:/Genera 3D dalla planimetria/}).click();const dialog=page.getByRole('dialog');await dialog.getByRole('spinbutton',{name:'Chiusura vuoti',exact:true}).fill('0');await dialog.getByRole('button',{name:'Analizza planimetria',exact:true}).click();await expect(dialog.locator('.summary')).toContainText('1 stanze chiuse');await expect(dialog.getByRole('checkbox',{name:'Conferma apertura 1',exact:true})).not.toBeChecked();await expect(dialog.locator('.summary')).toContainText('0 aperture');await dialog.getByRole('checkbox',{name:'Conferma apertura 1',exact:true}).check();await dialog.getByRole('combobox',{name:'Tipo apertura 1',exact:true}).selectOption('window');await dialog.getByRole('spinbutton',{name:'Larghezza foglio in metri',exact:true}).fill('10');await dialog.getByRole('checkbox',{name:'Conferma scala verificata',exact:true}).check();await expect(dialog.locator('.summary')).toContainText('1 aperture');await page.screenshot({path:'test-results/oblique-opening-review.png'});await dialog.getByRole('button',{name:'Crea piano e modello 3D',exact:true}).click();
  await page.getByRole('link',{name:/Impostazioni/}).click();const downloadPromise=page.waitForEvent('download');await page.getByRole('button',{name:/Esporta JSON/}).click();const stream=await (await downloadPromise).createReadStream(),chunks:Buffer[]=[];for await(const chunk of stream!)chunks.push(Buffer.from(chunk));const project=JSON.parse(Buffer.concat(chunks).toString()),floor=project.building.floors[1];expect(validateProject(project)).toEqual([]);expect(floor.rooms).toHaveLength(1);expect(floor.walls.flatMap((wall:{openings:unknown[]})=>wall.openings)).toEqual([expect.objectContaining({type:'window',sill:.9})]);await page.reload();await expect(page.locator('.connection-pill')).toContainText('Modalità demo');expect(errors).toEqual([]);
});
